// Photoshop patterns for the pattern-filled outline / text fill.
//
// Krita drew pattern outlines into pixels. In Photoshop the text stays an
// editable text layer and the pattern goes into its layer style, so a tile
// generated by core/patterns.js (or loaded from a file) has to become a
// Photoshop pattern first: a scratch document receives the pixels, "Define
// Pattern" registers it, and a Pattern Overlay applied inside the scratch
// document is read back to learn the pattern's ID (layer styles reference
// patterns by name + ID). The scratch document is closed without saving.

import { ps, batchPlay, docInfo, num } from "./ps.js";
import { T } from "./settings.js";
import { hasImaging } from "./pixels.js";

function hashTile(tile) {
  let h = 2166136261 >>> 0;
  const step = Math.max(1, Math.floor(tile.rgba.length / 4096));
  for (let i = 0; i < tile.rgba.length; i += step) {
    h ^= tile.rgba[i];
    h = Math.imul(h, 16777619) >>> 0;
  }
  return `${tile.w}x${tile.h}-${h.toString(16)}`;
}

/** Existing pattern preset names (Photoshop's "Krita resources"). */
export async function listPatternNames() {
  try {
    const r = await batchPlay([{
      _obj: "get",
      _target: [{ _property: "presetManager" }, { _ref: "application", _enum: "ordinal", _value: "targetEnum" }],
    }]);
    const pm = r && r[0] && r[0].presetManager;
    for (const entry of pm || []) {
      if (entry && (entry._obj === "pattern" || entry._obj === "patternsClass" || /pattern/i.test(entry._obj || ""))) {
        return (entry.name || []).map(String);
      }
    }
  } catch (e) {
    // not available
  }
  return [];
}

async function withScratchDoc(w, h, fn) {
  const { app } = ps();
  const back = app.activeDocument;
  const doc = await app.createDocument({ width: w, height: h, resolution: 72, mode: "RGBColorMode", fill: "transparent", name: "TypeR scratch" });
  try {
    return await fn(doc);
  } finally {
    try {
      await doc.closeWithoutSaving();
    } catch (e) {
      // closed already
    }
    if (back) app.activeDocument = back;
  }
}

/**
 * Register `tile` ({w, h, rgba}) as a Photoshop pattern named `name`;
 * returns {name, id}. Cached by content, so the same tile is defined once.
 * Must run inside a modal scope.
 */
export async function ensurePattern(tile, name = "TypeR pattern") {
  if (!tile || !hasImaging()) return null;
  const key = hashTile(tile);
  const known = T.get("psPatterns", {}) || {};
  if (known[key]) return known[key];
  const pname = `${name} ${key.slice(-6)}`;
  const out = await withScratchDoc(tile.w, tile.h, async (doc) => {
    const img = await ps().imaging.createImageDataFromBuffer(tile.rgba, {
      width: tile.w, height: tile.h, components: 4, colorSpace: "RGB", chunky: true, colorProfile: "sRGB IEC61966-2.1",
    });
    await ps().imaging.putPixels({ documentID: doc.id, layerID: doc.activeLayers[0].id, imageData: img });
    img.dispose();
    await batchPlay([
      { _obj: "set", _target: [{ _ref: "channel", _property: "selection" }], to: { _enum: "ordinal", _value: "allEnum" } },
      { _obj: "make", _target: [{ _ref: "pattern" }], using: { _ref: [{ _ref: "property", _property: "selection" }, { _ref: "document", _enum: "ordinal", _value: "targetEnum" }] }, name: pname },
    ]);
    // learn the ID: apply it by name and read the effect back
    await batchPlay([{
      _obj: "set",
      _target: [{ _ref: "property", _property: "layerEffects" }, { _ref: "layer", _enum: "ordinal", _value: "targetEnum" }],
      to: { _obj: "layerEffects", patternFill: { _obj: "patternFill", enabled: true, pattern: { _obj: "pattern", name: pname } } },
    }]);
    const r = await batchPlay([{ _obj: "get", _target: [{ _property: "layerEffects" }, { _ref: "layer", _enum: "ordinal", _value: "targetEnum" }] }]);
    const fx = r && r[0] && r[0].layerEffects;
    const id = fx && fx.patternFill && fx.patternFill.pattern ? fx.patternFill.pattern.ID || fx.patternFill.pattern.Idnt : null;
    return { name: pname, id: id || "" };
  });
  known[key] = out;
  T.set("psPatterns", known);
  return out;
}

/** Pixels of an existing Photoshop pattern (for the preview): a scratch
 *  document filled with it. Must run inside a modal scope. */
export async function patternPixels(name, size = 128) {
  if (!hasImaging()) return null;
  return withScratchDoc(size, size, async (doc) => {
    await batchPlay([
      { _obj: "set", _target: [{ _ref: "channel", _property: "selection" }], to: { _enum: "ordinal", _value: "allEnum" } },
      { _obj: "fill", using: { _enum: "fillContents", _value: "pattern" }, pattern: { _obj: "pattern", name }, opacity: { _unit: "percentUnit", _value: 100 }, mode: { _enum: "blendMode", _value: "normal" } },
    ]);
    const res = await ps().imaging.getPixels({ documentID: doc.id, componentSize: 8, applyAlpha: false, colorSpace: "RGB" });
    const img = res.imageData;
    const data = await img.getData({ chunky: true });
    const comps = img.components;
    const rgba = new Uint8Array(img.width * img.height * 4);
    for (let i = 0; i < img.width * img.height; i++) {
      rgba[i * 4] = data[i * comps];
      rgba[i * 4 + 1] = data[i * comps + 1];
      rgba[i * 4 + 2] = data[i * comps + 2];
      rgba[i * 4 + 3] = comps >= 4 ? data[i * comps + 3] : 255;
    }
    const w = img.width;
    const h = img.height;
    img.dispose();
    return { w, h, rgba };
  });
}

export function docResolution() {
  const d = docInfo();
  return d ? num(d.resolution) : 72;
}
